#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> tiles(3);
    for (string& tile : tiles)
        cin >> tile;

    int answer = 2;

    for (int i = 0; i < 3; ++i) {
        for (int j = i + 1; j < 3; ++j) {
            if (tiles[i] == tiles[j] ||
                (tiles[i][1] == tiles[j][1] &&
                 abs(tiles[i][0] - tiles[j][0]) <= 2)) {
                answer = 1;
            }
        }
    }

    sort(tiles.begin(), tiles.end());

    if (tiles[0] == tiles[1] && tiles[1] == tiles[2]) {
        answer = 0;
    } else if (tiles[0][1] == tiles[1][1] &&
               tiles[1][1] == tiles[2][1]) {
        vector<int> ranks = {
            tiles[0][0] - '0',
            tiles[1][0] - '0',
            tiles[2][0] - '0'
        };
        sort(ranks.begin(), ranks.end());

        if (ranks[1] == ranks[0] + 1 &&
            ranks[2] == ranks[1] + 1) {
            answer = 0;
        }
    }

    cout << answer << '\n';
    return 0;
}

